#!/usr/bin/env python3
"""Writes hubs_texts.h from the Electron build's src/dev/hubs.js.

  chromium/tools/gen_hub_texts.py <hubs.js> <hubs_texts.h>

Each hub template's folders and files as C++ data, word for word, with
{{NAME}} and {{TODAY}} where the hub name and today's date go.
"""
import json
import subprocess
import sys

HEADER = '''// Copyright 2026 The Meridian Authors
// Use of this source code is governed by a BSD-style license that can be
// found in the LICENSE file.

// Generated by chromium/tools/gen_hub_texts.py from src/dev/hubs.js.

#ifndef CHROME_BROWSER_MERIDIAN_WORKBENCH_HUBS_TEXTS_H_
#define CHROME_BROWSER_MERIDIAN_WORKBENCH_HUBS_TEXTS_H_

#include "base/containers/span.h"
#include "base/memory/raw_ptr_exclusion.h"

namespace meridian::workbench::texts {

struct HubFile {
  const char* path;
  const char* content;
};

struct HubTemplate {
  const char* id;
  const char* label;
  const char* description;
  // Static data, never freed.
  RAW_PTR_EXCLUSION base::span<const char* const> dirs;
  RAW_PTR_EXCLUSION base::span<const HubFile> files;
  const char* skill;
};

'''
FOOTER = '''
}  // namespace meridian::workbench::texts

#endif  // CHROME_BROWSER_MERIDIAN_WORKBENCH_HUBS_TEXTS_H_
'''


def raw(s):
  assert ')meridian"' not in s
  return 'R"meridian(%s)meridian"' % s


def main():
  script = open(sys.argv[1], encoding='utf-8').read().replace(
      'const today = () =>', 'const today = () => "{{TODAY}}"; const _unusedToday = () =>')
  script += ('\nmodule.exports = { out: Object.fromEntries(Object.entries(TEMPLATES).map(([id, t]) => '
             '[id, { label: t.label, description: t.description, dirs: t.dirs, files: t.files("{{NAME}}"), '
             'skill: SKILL_MD(id) }])), CLAUDE_MD, COMMON_GITIGNORE };\n')
  out = subprocess.run(
      ['node', '-e',
       'const m = new module.constructor(); m.paths = module.paths; '
       'm._compile(require("fs").readFileSync(0, "utf8"), "hubs.js"); '
       'process.stdout.write(JSON.stringify(m.exports));'],
      input=script, capture_output=True, text=True, check=True).stdout
  data = json.loads(out)
  lines = [HEADER]
  lines.append('inline constexpr char kHubClaudeMd[] = %s;\n\n' % raw(data['CLAUDE_MD']))
  lines.append('inline constexpr char kHubGitignore[] = %s;\n\n' % raw(data['COMMON_GITIGNORE']))
  for tid, t in data['out'].items():
    ident = tid.capitalize()
    lines.append('inline constexpr const char* k%sDirs[] = {%s};\n' %
                 (ident, ', '.join(json.dumps(d) for d in t['dirs'])))
    lines.append('inline constexpr HubFile k%sFiles[] = {\n' % ident)
    for rel, content in t['files'].items():
      lines.append('    {%s, %s},\n' % (json.dumps(rel), raw(content)))
    lines.append('};\n\n')
  lines.append('inline constexpr HubTemplate kHubTemplates[] = {\n')
  for tid, t in data['out'].items():
    ident = tid.capitalize()
    lines.append('    {%s, %s, %s, k%sDirs, k%sFiles,\n     %s},\n' %
                 (json.dumps(tid), json.dumps(t['label']),
                  json.dumps(t['description']), ident, ident, raw(t['skill'])))
  lines.append('};\n')
  open(sys.argv[2], 'w', encoding='utf-8').write(''.join(lines) + FOOTER)


main()
